  'about.bookshopLeadIn': "Realizzato dalla stessa piccola impresa che gestisce la nostra libreria:",
  "about.eyebrow": "Informazioni su Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — Chi siamo",
  "about.founderHeading": "📖 Chi è la fondatrice",
  "about.founder.p1": "Ciao, sono Concepcion, la fondatrice di Luminous StockHaven.",
  "about.founder.p2": "Non vengo da una grande azienda tecnologica e non siedo in un ufficio aziendale. Sono una piccola commerciante, proprio come te. Gestisco cinque negozi online, specializzati in libri e accessori artigianali per chi ama i libri.\nCome molti commercianti indipendenti, sono arrivata al limite cercando di gestire l’inventario di più sedi, tenere traccia degli ISBN degli editori insieme ai miei SKU artigianali e gestire gli ordini ai fornitori con fogli di calcolo scomodi. Quando ho cercato un’app che mi aiutasse, ne ho provate sei diverse. Ognuna era completamente incompleta, incredibilmente confusa o predatoria: centinaia di dollari al mese per strumenti di base.",
  "about.founder.p3": "Frustrata da un settore che strozza i creatori indipendenti, ho deciso di costruire la mia soluzione. Ho creato Luminous StockHaven per necessità, per gestire le mie attività in modo pulito, efficiente e con totale tranquillità.",
  "about.founder.p4": "Ho deciso di aprire questa piattaforma al pubblico a un prezzo onesto e accessibile, perché ogni piccolo commerciante merita strumenti che funzionino davvero senza rischiare i propri guadagni. Siamo indipendenti, fieramente protettivi della nostra comunità e creati da una commerciante, per i commercianti.",
