  "plans.title": "Confronta i piani StockHaven",
  "plans.intro": "Un unico account, qualunque piano tu scelga: Business copre fino a cinque attività. I prezzi sono mensili in dollari USA e i nuovi clienti idonei del sito web possono ricevere una prova di sette giorni tra Essentials e Business. Il passaggio da un abbonamento Essentials esistente a Business non riavvia la prova né crea un'altra prova gratuita. I prezzi dei piani del sito web sono al netto delle tasse applicabili, se presenti. L'addebito esatto ti verrà mostrato prima di autorizzare un abbonamento.",
