  "plans.mobileIncludedNote": "Entrambi i piani del sito web includono il compagno mobile, quindi chi si abbona dal sito web non paga mai anche la tariffa mensile mobile.",
  "plans.priceNote": "Essentials costa $14.99/mese più le tasse applicabili, se presenti. Business costa $29.99/mese più le tasse applicabili, se presenti. Eventuali tasse dovute vengono determinate durante il pagamento presso il fornitore e devono comparire nel totale finale prima del pagamento. Questa pagina di confronto non è un preventivo fiscale né un'autorizzazione al pagamento.",
  "plans.mobilePriceNote": "Il piano solo mobile costa $4.99/mese al prezzo base statunitense previsto. L'App Store o Google Play mostra il prezzo effettivo dell'abbonamento nella tua zona e le eventuali tasse applicabili prima dell'acquisto. I limiti di prodotti, sedi e personale sono stabiliti al lancio, separatamente dai livelli del sito web.",
  "plans.planChangeNote": "Una modifica del piano del sito web deve essere confermata dal fornitore di fatturazione. Il nuovo prezzo, la data di decorrenza e l'eventuale conguaglio saranno spiegati prima che la modifica venga autorizzata. Un passaggio a un piano superiore non deve creare un secondo abbonamento.",
  "plans.providerNote": "Prezzi, addebiti e prove sono gestiti dal fornitore tramite cui ti abboni — App Store, Google Play, sito web o Shopify — mai da questa pagina.",
