  "upgrade.upgradeNeverRestartsTrial": "Il passaggio a un piano superiore non riavvia mai la prova gratuita.",
  "upgrade.trialHistoryNote": "Se paghi Essentials e passi a Business, mantieni lo stesso account cliente e la stessa cronologia della prova. Business non include un'ulteriore prova di sette giorni. Se passi a un piano superiore mentre la prova originale è ancora in corso, la data di fine originale non si azzera.",
  "upgrade.providerConfirmNote": "Le modifiche al piano richiedono la conferma del fornitore di fatturazione. Qualsiasi differenza di prezzo, conguaglio e data di decorrenza devono essere mostrati prima che tu approvi la modifica. Un passaggio a un piano superiore non deve creare un secondo abbonamento simultaneo.",
  "upgrade.chargedThroughProviderNote": "Le modifiche al piano vengono addebitate tramite il fornitore di fatturazione. Puoi annullare l'abbonamento da questa pagina usando il pulsante Annulla l'abbonamento sotto il tuo piano attuale, oppure dalle Impostazioni. L'annullamento interrompe i rinnovi futuri alla fine del periodo pagato; non termina mai l'accesso immediatamente. La visualizzazione di queste opzioni non addebita nulla agli spazi di lavoro gratuiti esistenti.",
