  "billing.cancel.refundWindowOpen": "Hai annullato entro 3 giorni dal primo addebito pagato, quindi potresti avere diritto al rimborso di quel primo pagamento. L'annullamento non emette di per sé il rimborso: richiedilo tramite {contact}.",
  "billing.cancel.refundWindowClosed": "L'annullamento di per sé non emette un rimborso. I rimborsi si applicano solo entro 3 giorni dal primo addebito pagato andato a buon fine, richiesti tramite {contact}.",
