  "import.eyebrow": "Dati",
  "import.title": "Centro importazioni",
  "import.subtitleStart": "Tre operazioni separate con fogli di calcolo, così una correzione di prezzo non può mai arrivare come ricevuta di scorte. Tutto finisce in",
  "import.subtitleRest": " soltanto, e nulla viene scritto finché una prova a secco non è superata.",
  "import.createBusinessFirst": "Crea prima un'attività: i prodotti importati appartengono a un'attività.",
  "import.createBusinessFirstShort": "Crea prima un'attività.",
  "import.whatEachDoes": "Cosa fa ogni operazione",
  "import.createTitle": "Crea nuovi prodotti",
  "import.createDesc": "aggiunge righe non ancora presenti nel catalogo. SKU e codici a barre duplicati già in uso vengono saltati, e le scorte iniziali possono finire in una sede a tua scelta come ricevuta.",
  "import.updateTitle": "Aggiorna i prodotti esistenti",
  "import.updateDesc": "abbina ogni riga per SKU o ID record e mostra il vecchio valore accanto a quello nuovo proposto. Le celle vuote lasciano invariato il valore salvato, a meno che tu non chieda di cancellare i vuoti, e le quantità non vengono mai toccate.",
  "import.receiveModeTitle": "Ricevi scorte",
  "import.receiveModeDesc": "aggiunge le quantità in arrivo a una sede e scrive una ricevuta nel registro dei movimenti per ogni riga. Ogni lotto è contrassegnato, così lo stesso foglio non può essere ricevuto due volte.",
  "import.excelNote": "Le cartelle di lavoro Excel (.xlsx) vengono lette direttamente: scegli il foglio di lavoro e le colonne vengono abbinate per te. I codici restano interi: un UPC salvato come testo mantiene le sue cifre e gli zeri iniziali. Le righe che non possono essere importate vengono elencate con un motivo",
