  'settings.details.taxRate': 'La mia aliquota fiscale',
  'settings.details.taxRateHint': 'Impostala una volta. Ogni nuovo ordine di vendita compila la propria imposta da questa aliquota — puoi comunque modificare l’imposta su un singolo ordine.',
  'settings.details.gs1Prefix': "Prefisso aziendale GS1",
  'settings.details.gs1PrefixHint': "Solo se hai una licenza di prefisso da GS1. Impostalo una volta e il generatore di codici della scheda prodotto potrà creare veri codici UPC ed EAN commerciali dai tuoi numeri — ognuno usato una sola volta e mai riutilizzato. Lascialo vuoto se non ne hai uno; l’app non inventa mai un prefisso.",
