  "print.style.title": "Stile dei documenti",
  "print.style.desc": "Rendi tuoi i tuoi documenti. Queste scelte vestono la tua fattura, ricevuta, bolla di accompagnamento, documenti di reso, schede prodotto, fogli di conteggio e liste di prelievo — e vengono ricordate per la tua attività.",
