  "training.lessons.owner-shipping-labels.step1": "Il Centro stampa ha uno stile Etichetta di spedizione in entrambi i piani: scegli un ordine del cliente e stampa un’etichetta 4×6 con nome e indirizzo dell’acquirente e la tua attività come mittente.",
  "training.lessons.owner-shipping-labels.step2": "L’etichetta è senza marchio, come ogni documento per il cliente: porta solo il nome della tua attività — mai il nome di questa app — così un pacco dal tuo negozio sembra venire dal tuo negozio.",
  "training.lessons.owner-shipping-labels.step3": "L'indirizzo del cliente viene conservato con i suoi ordini per 90 giorni dopo il suo ultimo ordine, e l'etichetta parte dall'indirizzo salvato dell'ordine quando ne ha uno; un indirizzo digitato al momento della stampa per un'etichetta singola non viene salvato. Il nome si compila comunque dall'ordine, così l'etichetta corrisponde ai documenti.",
  "training.lessons.owner-shipping-labels.step4": "L’etichetta si stampa attraverso le stesse quattro connessioni di tutte le etichette — Bluetooth, Wi-Fi, Ethernet e USB — e una stampante termica 4×6 è il formato standard per essa.",
  "training.lessons.owner-shipping-labels.step5": "Hai comprato l'affrancatura dal corriere? In questa stessa sezione puoi caricare il file della sua etichetta — PDF, PNG o JPG — e resta salvato sull'ordine per sempre: il tuo archivio, a portata di mano in caso succeda qualcosa. Si stampa nella sua dimensione reale 4×6. L'app non vende mai affrancatura, quindi il prezzo del corriere è l'unico prezzo — e sempre quello giusto.",
  "training.lessons.owner-shipping-labels.title": "Etichette di spedizione per gli ordini dei clienti",
  "training.lessons.print-shipping-label.step1": "Quando un ordine è pronto da spedire, apri il Centro stampa, scegli lo stile Etichetta di spedizione e poi scegli l’ordine del cliente. Il nome dell’acquirente viene compilato dall’ordine.",
  "training.lessons.print-shipping-label.step2": "Controlla l'indirizzo a cui va il pacco. Quando l'ordine contiene l'indirizzo del cliente — conservato per 90 giorni dopo il suo ultimo ordine — si compila per te; un indirizzo che digiti al momento della stampa non viene salvato, quindi controlla con attenzione il codice postale e l'ultima riga prima di stampare.",
  "training.lessons.print-shipping-label.step3": "Il nome della tua attività si stampa in alto come mittente. Se vuoi anche il tuo indirizzo sull’etichetta, scrivilo nel campo indirizzo del mittente; lascialo vuoto se preferisci che non compaia.",
  "training.lessons.print-shipping-label.step4": "Stampa su un’etichetta 4×6 — una stampante termica per etichette è la scelta abituale — o su qualsiasi stampante con il pulsante di stampa del browser. Incolla l’etichetta ben piatta sul pacco, dove non si pieghi su un bordo.",
  "training.lessons.print-shipping-label.step5": "Se l'affrancatura è stata comprata dal corriere, salva invece il suo file di etichetta sull'ordine: carica il PDF, PNG o JPG che ti ha dato il corriere nella sezione L'etichetta del tuo corriere. Resta sull'ordine come tuo archivio e si stampa nella sua dimensione reale 4×6 — e l'etichetta indirizzo dell'app è sempre lì quando preferisci usarla.",
  "training.lessons.print-shipping-label.title": "Stampa un’etichetta di spedizione",
