  "pos.clover.help": "Collega Clover e ogni vendita alla cassa toglie i suoi articoli dalle scorte qui, da sola — nulla da digitare a fine giornata.",
  "pos.clover.connect": "Collega Clover",
  "pos.clover.notConfigured": "I collegamenti Clover non sono ancora attivati. L'importazione CSV qui sotto funziona oggi.",
