  "pos.toast.help": "Toast si collega tramite il programma partner di Toast. Quando le credenziali partner del tuo ristorante sono pronte, incollale qui e ogni vendita Toast toglie i suoi articoli dalle scorte qui, da sola.",
  "pos.toast.connect": "Collega Toast",
  "pos.toast.connectedToast": "Toast collegato. Le sue vendite ora contano qui.",
