  "workforce.messages.discard": "Eliminala",
  "workforce.messages.micDenied": "Il microfono è bloccato, quindi non è possibile registrare una nota vocale. Puoi consentire il microfono nelle impostazioni del browser — oppure inviare semplicemente un messaggio scritto.",
  "workforce.messages.voiceFailed": "Impossibile inviare quella nota vocale. Riprova.",
  "workforce.messages.sentLabel": "Inviato",
  "workforce.messages.receivedLabel": "Ricevuto",
  "workforce.messages.readLabel": "Letto",
  "apiErrors.notFound.voiceNoteFound": "Nota vocale non trovata.",
  "apiErrors.invalidValue.sendVoiceRecording": "Invia una registrazione vocale di pochi minuti al massimo.",
  "apiErrors.invalidValue.recordingNotPrepared": "Impossibile preparare quella registrazione: registrala di nuovo.",
  "training.lessons.messages-private.step5": "Puoi anche inviare una nota vocale: tocca il microfono accanto alla casella del messaggio, parla e tocca stop. Ascoltala prima — poi inviala, oppure eliminala e registra di nuovo. Quando qualcuno te ne invia una, tocca riproduci per sentire la sua vera voce.",
  "training.lessons.owner-messages-oversight.step5": "Conferme di lettura: quando un membro del team legge un messaggio che gli hai inviato, lo vedi segnato come letto. Personale e manager vedono le conferme di lettura gli uni degli altri allo stesso modo, in entrambe le direzioni.",
  "training.lessons.owner-messages-oversight.step6": "La tua lettura è invisibile. Quando leggi un messaggio che un membro del personale ti ha inviato, quella persona non vede mai una conferma di lettura — e non devi dire al tuo team che le loro conversazioni sono salvate nell’app e che tu, il proprietario, puoi leggerle. Questa supervisione fa parte del prendersi cura del tuo negozio.",
  "training.lessons.owner-messages-oversight.step7": "Quello che fai dei messaggi negativi tra membri del personale dipende da te. Lascia correre, parla con qualcuno in privato o intervieni — la scelta è tua, e non devi mai dire dove l’hai visto.",
  "staffLib.perm.returnsComplete": "Completare rimborsi e cambi",
  "staffLib.area.returnsAccess": "Approvazione dei resi",
  "staff.memberDialog.returnsAccessHint": "Con questa spunta, questa persona può approvare un reso e completare il rimborso o il cambio. Senza, un reso che avvia attende il titolare o un membro del team approvato.",
  "returns.waitingApproval": "In attesa dell’approvazione del titolare o di un membro del team approvato.",
