  "staffLib.perm.locationsCreate": "Aggiungi nuove sedi",
  "staffLib.area.locationsAccess": "Aggiunta di sedi",
  "staff.memberDialog.locationsAccessHint": "Con questa spunta, questa persona può aggiungere nuove sedi. Senza, solo il titolare può aggiungere una sede, e i pulsanti per aggiungere non le vengono mostrati.",
  "apiErrors.locationsCreateReserved": "Solo il titolare, o un membro del team che il titolare ha autorizzato ad aggiungere sedi, può aggiungere una sede.",
  "settings.policies.title": "Politiche e termini del tuo negozio",
  "settings.policies.ownerDescription": "Il tuo negozio, le tue regole. Scrivi qui le politiche del tuo negozio e i tuoi termini e condizioni: digitali, oppure carica un file. Ogni nuovo membro del team li vede una volta quando inizia, e tutto il tuo team può leggerli qui in qualsiasi momento. Solo tu puoi modificarli.",
  "settings.policies.memberDescription": "Le politiche e i termini propri del tuo negozio, scritti dal titolare. Solo il titolare può modificarli.",
