  "settings.platformPolicies.title": "Politiche di Luminous StockHaven",
  "settings.platformPolicies.description": "I termini e le politiche propri dell’app. Restano con l’app, e tutto il team può leggerli qui.",
  "staffWelcome.policiesIntro": "Prima di iniziare: le politiche e i termini del tuo negozio, scritti dal titolare.",
  "plansLib.includes.storePolicies": "Le tue politiche e i tuoi termini del negozio in Impostazioni, da leggere per tutto il tuo team",
  "apiErrors.businessPoliciesOwnerOnly": "Solo il titolare può modificare le politiche e i termini di questo negozio.",
  "apiErrors.policyFileInvalid": "Invia un file PDF, di testo, Word o OpenDocument sotto i 2 MB.",
  "apiErrors.policyTextTooLong": "Questo documento è troppo lungo da scrivere qui. Puoi invece caricarlo come file.",
  "training.lessons.owner-store-policies.title": "Le politiche e i termini del tuo negozio",
  "training.lessons.owner-store-policies.step1": "Apri Impostazioni e cerca la scheda Politiche e termini del tuo negozio. Contiene due documenti: le Politiche del tuo negozio — le regole della casa — e i tuoi Termini e condizioni.",
  "training.lessons.owner-store-policies.step2": "Ogni documento può essere scritto direttamente lì, oppure caricato come file (PDF, testo, Word o OpenDocument, fino a 2 MB). È una cosa o l’altra: salvare il testo sostituisce un file, e caricare un file sostituisce il testo. Rimuovere un documento lo cancella.",
  "training.lessons.owner-store-policies.step3": "Il tuo team vede entrambi i documenti una volta, sulla pagina di benvenuto quando inizia, e può leggerli in qualsiasi momento nelle proprie Impostazioni. Per il tuo team sono di sola lettura: solo tu puoi scriverli o modificarli.",
  "training.lessons.owner-store-policies.step4": "Ogni attività conserva i propri documenti: ciò che scrivi qui appartiene solo a questo negozio e non appare mai in un’altra attività. I termini e le politiche propri di Luminous StockHaven vivono accanto ai tuoi in Impostazioni, e tutti possono leggere anche quelli.",
  "training.lessons.welcome-basics.step5": "Le politiche e i termini del tuo negozio vengono mostrati una volta sulla tua pagina di benvenuto, e vivono in Impostazioni, dove puoi leggerli in qualsiasi momento.",
  "apiErrors.policyDocNotFound": "Quel documento non è uno dei due.",
  "apiErrors.policyFileNotFound": "Nessun file è salvato per quel documento.",
