  "staffLib.area.lowStockAccess": "Scorte basse",
  "staff.memberDialog.lowStockAccessHint": "Con il primo segno di spunta, questa persona vede gli avvisi di scorte basse — il riquadro Richiede attenzione, la pagina Scorte basse e i contrassegni di livello basso. Con il secondo segno di spunta, può modificare il punto di riordino di un prodotto; senza, il campo Punto di riordino resta visibile, ma una modifica non verrà salvata.",
  "apiErrors.reorderChangeReserved": "Solo il titolare, o un membro del team che il titolare ha autorizzato a modificare i punti di riordino, può modificare un punto di riordino.",
  "apiErrors.alertsViewReserved": "Solo il titolare, o un membro del team che il titolare ha autorizzato a vedere gli avvisi di scorte basse, può vedere gli avvisi di scorte basse.",
