  "settings.policyQuiz.addOpen": "Aggiungi una domanda aperta",
  "settings.policyQuiz.correct": "Corretta",
  "settings.policyQuiz.empty": "Ancora nessuna domanda. Senza domande, questa formazione è solo la lettura.",
  "settings.policyQuiz.expected": "Risposta attesa",
  "settings.policyQuiz.expectedHint": "La risposta che ti aspetti, con parole tue. Una risposta che corrisponde quasi parola per parola conta come corretta sul posto; le altre arrivano a te per un controllo.",
  "settings.policyQuiz.hint": "Scrivi domande su questo documento per il tuo team. Una persona risponde durante la Formazione quando spunti questa formazione per lei nella sua scheda Personale. Non c'è limite al numero di domande che puoi scrivere.",
  "settings.policyQuiz.mcLabel": "Scelta multipla",
