  "settings.policyQuiz.passLineHint": "Il punteggio — contando solo le risposte a scelta multipla — che serve a una persona per finire questa formazione.",
  "settings.policyQuiz.question": "Domanda",
  "settings.policyQuiz.remove": "Rimuovi",
  "settings.policyQuiz.save": "Salva le domande",
  "settings.policyQuiz.saved": "Domande salvate.",
  "settings.policyQuiz.title": "Domande per il tuo team",
  "staff.memberDialog.trainingAccessHint": "Leggere le politiche del negozio e i termini è per tutti. Queste spunte assegnano le formazioni con quiz che il proprietario crea accanto a ogni documento nelle Impostazioni.",
  "staffLib.area.trainingAccess": "Formazioni con quiz sulle politiche",
  "staffLib.perm.trainingPoliciesQuiz": "Formazione con quiz sulle politiche del negozio",
  "staffLib.perm.trainingTermsQuiz": "Formazione con quiz sui Termini e condizioni",
  "training.comment.placeholder": "Qualcosa su questa lezione…",
  "training.comment.send": "Invia commento",
  "training.comment.sent": "Il tuo commento è stato inoltrato al proprietario.",
  "training.comment.title": "Lascia un commento per il proprietario",
  "training.lessons.download-app.step1": "Luminous StockHaven può vivere sul tuo telefono o computer come una vera app — senza bisogno di app store.",
  "training.lessons.download-app.step2": "Apri Impostazioni e trova la scheda Scarica l'app. È lì per ogni ruolo, in entrambi i piani.",
  "training.lessons.download-app.step3": "Tocca il pulsante di installazione e segui le indicazioni del tuo dispositivo. L'app arriva sulla schermata iniziale con il nome e l'icona del negozio.",
  "training.lessons.download-app.step4": "Da allora aprila dalla schermata iniziale — accedi allo stesso modo e mostra lo stesso negozio.",
  "training.lessons.download-app.title": "Scarica l'app sul tuo dispositivo",
  "training.lessons.mgr-tax-rate.step1": "Gli ordini possono avere un'aliquota di imposta sulle vendite. Il proprietario imposta l'aliquota stessa nelle Impostazioni; è un'unica aliquota per tutto il negozio.",
  "training.lessons.mgr-tax-rate.step2": "Quando il proprietario spunta la sezione tasse per te nella tua scheda Personale, l'aliquota appare anche nelle tue Impostazioni e puoi tenerla aggiornata lì.",
  "training.lessons.mgr-tax-rate.step3": "L'aliquota è una percentuale — 8.25 significa che il cliente paga l'8.25% di imposta in più rispetto ai beni dell'ordine.",
  "training.lessons.mgr-tax-rate.step4": "Quando l'aliquota cambia, i nuovi ordini usano la nuova aliquota. Gli ordini già effettuati mantengono l'aliquota con cui sono stati fatti.",
  "training.lessons.mgr-tax-rate.title": "L'aliquota fiscale del negozio",
  "training.lessons.owner-confidentiality.step5": "Ecco tutta la mappa. Il tuo team vede il proprio lavoro — il suo orario, i suoi compiti, le sue buste paga, i suoi messaggi e le schermate del negozio che il suo ruolo apre. Non vede mai la tua prova, su quale piano è l'attività, quanto costa il piano, se un pagamento è andato a buon fine o che è stato raggiunto un limite del piano. Le superfici di denaro — fatturazione, fatture, metodi di pagamento — sono solo per il proprietario, sempre.",
  "training.lessons.owner-confidentiality.step6": "Se l'account viene mai fermato, questo è il messaggio esatto che vede il tuo team: “Le modifiche sono disattivate in questo momento. Non si può aggiungere né cambiare nulla al momento — chiedi al proprietario dell’attività se ti serve qualcosa.” Niente in esso nomina un piano, un prezzo o un pagamento.",
  "training.lessons.owner-confidentiality.step7": "E quando è un limite del piano a fermare qualcosa, questo è il messaggio esatto: “Non può essere aggiunto ora — chiedi al proprietario dell’attività.” Non dice mai che è stato raggiunto un limite — quello resta tra te e l'app.",
  "training.lessons.staff-builds.step1": "Una composizione mette insieme prodotti in un'unica cosa vendibile — un bundle, un kit, un set regalo. Le composizioni vivono nella schermata Composizioni nel menu.",
  "training.lessons.staff-builds.step2": "Apri una composizione per vedere cosa contiene: ogni prodotto componente e quanti di ciascuno usa la composizione.",
  "training.lessons.staff-builds.step3": "Quando una composizione viene creata o venduta, le scorte delle sue parti si muovono con essa — l'app mantiene i conteggi onesti per te.",
  "training.lessons.staff-builds.step4": "Se manca una parte o un conteggio sembra sbagliato, dillo al tuo responsabile invece di indovinare — le composizioni toccano molti prodotti in una volta.",
  "training.lessons.staff-builds.title": "Composizioni e bundle",
  "training.lessons.staff-cross-store.step1": "Quando la tua attività ha più di un negozio o sito, i negozi possono chiedersi scorte a vicenda. Queste richieste arrivano nella casella inter-negozi.",
  "training.lessons.staff-cross-store.step2": "Apri la casella dal menu per vedere cosa sta chiedendo un altro negozio e cosa è stato inviato al tuo negozio.",
  "training.lessons.staff-cross-store.step3": "Rispondi a una richiesta solo nel modo che ti ha mostrato il tuo responsabile — inviare scorte fuori cambia i conteggi del tuo negozio.",
  "training.lessons.staff-cross-store.step4": "Se una richiesta sembra sbagliata — l'articolo sbagliato o più di quanto hai — non indovinare. Segnalala al tuo responsabile.",
  "training.lessons.staff-cross-store.title": "La casella inter-negozi",
  "training.lessons.staff-reports.step1": "I rapporti raccolgono i numeri del negozio — vendite, scorte e altro — in un unico posto. I rapporti vivono nel menu.",
  "training.lessons.staff-reports.step2": "Apri un rapporto per vedere i suoi numeri per le date che copre. Le date fanno parte del rapporto: lo stesso rapporto su una settimana diversa racconta una storia diversa.",
  "training.lessons.staff-reports.step3": "Alcuni rapporti possono essere salvati fuori dall'app come file. Salva un rapporto fuori solo quando il tuo responsabile o il proprietario te lo ha chiesto.",
  "training.lessons.staff-reports.step4": "I numeri dei rapporti vengono dal lavoro reale del negozio — ordini, conteggi e movimenti — quindi inserimenti onesti ovunque mantengono i rapporti veri.",
  "training.lessons.staff-reports.title": "Leggere i rapporti",
  "training.lessons.welcome-basics.step6": "Quando hai finito, disconnettiti: un collegamento Esci si trova in fondo a ogni pagina, appena sopra la riga del copyright. Disconnettersi ti disconnette ovunque, su ogni dispositivo — così nessuno può entrare nel tuo account su uno schermo condiviso.",
